      "aprofundamento": "O **prontuário** reúne as informações sobre a saúde do paciente, e esses dados são dele. Médico e instituição são apenas **guardiões**: devem conservar o documento, mantê-lo sob sigilo e franqueá-lo ao titular.\n\nA lógica é a autonomia do paciente: quem decide sobre o próprio corpo precisa ter acesso às informações sobre ele. Daí o direito de acesso e de cópia, que o médico não pode negar.\n\nO sigilo protege o paciente contra terceiros, não contra ele mesmo. A banca troca titular e guardião, ou usa o sigilo como pretexto para negar acesso ao próprio paciente.",
