      "correcao": {
       "erro": "Admite que médico integrante da equipe de transplante constate a morte encefálica, desde que acompanhado de outro médico.",
       "certo": "A morte encefálica é constatada e registrada por dois médicos não participantes das equipes de remoção e transplante."
      },
      "aprofundamento": "O impedimento é absoluto porque a razão dele é o **conflito de interesses**. O médico da equipe de transplante quer que o órgão seja aproveitado; o da equipe de remoção quer retirá-lo. Nenhum deles pode decidir se o doador está morto.\n\nA presença de um segundo médico não corrige o problema, porque a lei exige que os **dois** sejam alheios às equipes. A garantia não está no número de assinaturas, mas na independência de quem assina.\n\nA pegadinha cria uma saída aparente com a palavra **acompanhado**. Desconfie sempre de condições que a lei não prevê para flexibilizar uma vedação.",
