      "aprofundamento": "O prazo mínimo existe por cautela contra a morte aparente: esperar permite que surjam os sinais de certeza. Mas, quando a morte é evidente desde logo, o motivo da espera desaparece, e a lei autoriza antecipar.\n\nPense em decapitação, esmagamento craniano ou carbonização: não há dúvida de que a pessoa morreu. Esperar só atrasaria a perícia, e o tempo pode alterar vestígios importantes.\n\nDois detalhes que a banca troca: quem decide são os **peritos**, e não a autoridade; e a antecipação deve ser **declarada no auto**, com a justificativa.",
