      "correcao": {
       "erro": "Afirma que a premoriência presume que o mais idoso morreu antes.",
       "certo": "Premoriência é a situação em que se prova que um morreu antes do outro; o direito brasileiro não presume ordem por idade e, sem prova, aplica a comoriência."
      },
      "aprofundamento": "A **premoriência** não é presunção, é fato provado: demonstra-se que alguém morreu antes do outro. Quando isso acontece, aplica-se a ordem real, e quem sobreviveu, ainda que por instantes, herdou.\n\nAlguns sistemas antigos presumiam a ordem por idade ou sexo, supondo que o mais frágil morreria antes. O Código Civil brasileiro rejeita essas presunções: sem prova da precedência, aplica-se a comoriência do artigo citado.\n\nA pegadinha importa a presunção por idade. Lembre: no Brasil, ou se prova quem morreu antes, ou se presume a simultaneidade.",
