     "assertiva": "Livores fixos em regiões que não são de declive na posição em que o cadáver foi encontrado sugerem que o corpo foi movimentado depois da fixação.",
     "gabarito": "C",
     "comentario": {
      "resumo": "Livores **fixos** não migram: se não batem com a posição atual, o corpo foi **mudado de posição** depois de algumas horas.",
      "palavras_chave": [
       "livores fixos",
       "corpo movimentado"
      ],
      "aprofundamento": "Nas primeiras horas, os livores ainda migram: se o corpo é virado, o sangue desce para o novo declive. Com o tempo, o sangue extravasa dos vasos e impregna os tecidos, e os livores se **fixam**: não mudam mais de lugar.\n\nAssim, se o cadáver é encontrado de costas, mas os livores fixos estão no peito e no rosto, ele ficou de bruços por várias horas e foi virado depois. Livores em dois planos opostos indicam mudança de posição durante a fase de transição.\n\nEsse é um dos dados mais úteis na investigação de encenação de cena. A banca pode dizer que os livores sempre acompanham a posição atual, ignorando a fixação.",
      "exemplo": "O corpo está deitado de costas na cama, mas tem livores fixos no abdome e na face. O perito conclui que ele permaneceu de bruços por horas e foi depois reposicionado.",
      "memorize": "Livores fixos fora do declive atual = corpo movido depois da fixação."
     }
