      "aprofundamento": "A **mancha verde** é o primeiro sinal da putrefação, e a putrefação precisa de tempo para que as bactérias intestinais produzam gases suficientes para colorir a pele. Por isso ela não aparece nas primeiras horas, mas em regra no fim do primeiro dia.\n\nO clima altera muito esse tempo: no calor, ela surge antes; no frio, demora. Por isso as faixas apresentadas variam entre autores, e o resumo registra essa divergência.\n\nNas primeiras horas, o que se vê são os sinais abióticos consecutivos: resfriamento, livores, rigidez. A pegadinha antecipa muito um fenômeno tardio, colocando-o junto dos fenômenos iniciais.",
