      "aprofundamento": "O resfriamento cadavérico é lento, sobretudo no começo. Há inclusive um período inicial em que a temperatura quase não cai, porque o corpo ainda conserva calor interno. Depois, a perda se acelera, até que o corpo se iguale ao ambiente.\n\nAs estimativas clássicas falam em queda de cerca de meio grau por hora nas primeiras horas e de cerca de um grau depois. São números médios, sujeitos a ambiente, roupas e massa corporal.\n\nO valor da assertiva é muito superior a qualquer estimativa da doutrina: com ele, o corpo chegaria à temperatura ambiente em poucas horas, o que não ocorre. A banca infla números para tornar o item errado.",
