      "aprofundamento": "A **exumação** é medida invasiva, que mexe com o respeito aos mortos e com o sentimento da família. Por isso a lei a cerca de formalidades: dia e hora previamente marcados e auto circunstanciado de tudo o que for feito.\n\nO agendamento permite que peritos, autoridade e eventuais interessados estejam presentes, e o auto documenta a cadeia de custódia: como estava a sepultura, o caixão, o corpo e o que foi retirado. Sem esse registro, a defesa poderia questionar se o corpo examinado é realmente o da vítima.\n\nNão confunda **exumação**, retirar da sepultura, com **inumação**, sepultar. A banca troca os termos ou dispensa o auto.",
