      "aprofundamento": "O administrador do cemitério, público ou particular, tem o **dever** de colaborar, porque detém a informação que localiza o corpo. A lei reforça esse dever com a consequência penal: recusar é desobediência.\n\nA pesquisa pela autoridade é solução subsidiária, para quando o administrador se recusa ou não há quem indique a sepultura. Não é uma alternativa que transforma o dever em opção.\n\nA pegadinha usa **pode recusar-se** para converter dever em faculdade. Sempre que a lei fala em indicará, sob pena de desobediência, a recusa é ilícita.",
