      "aprofundamento": "O sêmen tem dois componentes: os espermatozoides, produzidos nos testículos, e o líquido seminal, produzido em grande parte pela próstata e pelas vesículas seminais. A vasectomia interrompe o caminho dos espermatozoides, mas não a produção do líquido.\n\nPor isso, mesmo em agressor vasectomizado ou azoospérmico, a perícia detecta o **antígeno prostático específico** (PSA, ou p30) e a **fosfatase ácida**, que vêm da próstata. Esses marcadores demonstram a presença de sêmen sem depender de espermatozoides.\n\nA pegadinha liga o marcador prostático ao espermatozoide. A pista está no próprio nome: o antígeno é prostático.",
