      "aprofundamento": "A **importunação sexual** foi criada para preencher uma lacuna: condutas como a de quem se esfrega em alguém no transporte público ou a beija à força eram graves demais para contravenção e não se enquadravam no estupro por falta de violência ou grave ameaça.\n\nOs elementos do tipo são: praticar ato libidinoso, contra alguém, **sem sua anuência**, com finalidade de satisfazer a lascívia própria ou de terceiro. Não há violência nem grave ameaça.\n\nA fronteira com o estupro é justamente o meio: se houver violência ou grave ameaça, o crime é de estupro; se a vítima for vulnerável, estupro de vulnerável. A banca pode exigir violência na importunação ou dispensar o fim libidinoso.",
