      "aprofundamento": "A lei protege a vítima adolescente com dois regimes. Até os 14 anos incompletos, o crime é de estupro de vulnerável, com pena própria e sem exigir violência. A partir dos 14 e até os 18, o estupro exige violência ou grave ameaça, mas é **qualificado** pela idade da vítima.\n\nA lógica é graduar a proteção: a pessoa entre 14 e 18 anos já pode consentir validamente, mas, se for estuprada, a menoridade torna o crime mais grave.\n\nA pegadinha troca 14 por 16, criando uma lacuna entre as faixas. As faixas legais se encaixam sem buraco: abaixo de 14, vulnerável; de 14 a 18, qualificadora.",
