      "aprofundamento": "A coleta é a etapa mais sensível da **cadeia de custódia**: um vestígio mal coletado pode ser contaminado, degradado ou perdido. Por isso a lei dá preferência ao perito oficial, que tem formação técnica para coletar e encaminhar corretamente à central de custódia.\n\nO termo é **preferencialmente**, e não exclusivamente. Em situações de urgência, ou quando não há perito disponível, outros agentes podem coletar, desde que observem as etapas da cadeia de custódia e documentem o procedimento.\n\nA banca troca preferencialmente por exclusivamente, ou por facultativamente. A palavra da lei é a do meio-termo.",
