      "aprofundamento": "A **importunação sexual** surgiu justamente para dar resposta penal séria a condutas que antes ficavam na contravenção de importunação ofensiva ao pudor, punida de forma branda. O legislador quis marcar a gravidade dessas condutas, e por isso fixou pena de **reclusão**.\n\nA pena prevista no artigo citado tem cláusula de **subsidiariedade expressa**: aplica-se se o ato não constitui crime mais grave. Se houver violência ou grave ameaça, o fato é estupro; se a vítima for vulnerável, estupro de vulnerável.\n\nA pegadinha rebaixa a pena para detenção, com patamar de infração de menor potencial ofensivo. Lembre: importunação é crime de médio potencial, com reclusão.",
