      "aprofundamento": "O **cogumelo de espuma** forma-se porque a vítima, ainda viva sob a água, continua tentando respirar. A agitação do ar com o líquido e o muco das vias aéreas produz uma espuma fina e persistente, que extravasa pela boca e pelo nariz.\n\nDaí seu valor: indica que houve movimentos respiratórios no meio líquido, ou seja, que a pessoa estava viva ao submergir. Um corpo jogado na água depois de morto, em regra, não o apresenta.\n\nO sinal é sugestivo, não absoluto, e desaparece com a putrefação ou a manipulação do corpo. A banca pode dizer que ele surge em corpos lançados mortos na água.",
