      "aprofundamento": "O sistema de Vucetich, adotado no Brasil, classifica as impressões em quatro tipos fundamentais (arco, presilha interna, presilha externa e verticilo). A fórmula datiloscópica representa esses tipos com símbolos diferentes conforme o dedo.\n\nPara os **polegares**, usam-se **letras** (A, I, E, V); para os demais dedos, **números** (1, 2, 3, 4), na mesma ordem dos tipos. A fórmula se escreve como fração, com a mão direita em cima e a esquerda embaixo.\n\nA pegadinha inverte letras e números. Lembre que o polegar, o dedo que 'abre' a série, recebe a letra.",
