      "aprofundamento": "A ferida incisa é produzida por instrumento cortante que desliza sobre a pele. No início do movimento, o gume penetra com mais força e a ferida é mais profunda; à medida que a mão se afasta, a pressão diminui, e o gume passa a apenas arranhar a superfície. Esse arranhão final é a **cauda de escoriação**.\n\nPor isso a cauda marca o **fim** do corte e permite inferir o sentido do golpe, informação útil para distinguir agressor destro ou canhoto, ou suicídio de homicídio, junto com outros elementos.\n\nA pegadinha troca o final pelo início. Pense no movimento: o corte começa fundo e termina raso.",
