      "aprofundamento": "Nas armas de projéteis múltiplos (espingardas com chumbo), os balins saem juntos e se afastam à medida que avançam. A figura que formam no alvo é a **rosa de tiro**, e seu diâmetro cresce com a distância. Isso permite estimar de que distância o disparo foi feito.\n\nA estimativa, porém, não é universal: a abertura depende do choke (estrangulamento do cano), do comprimento do cano e da munição. Por isso, para converter o diâmetro em distância, o perito faz **disparos comparativos** com a mesma arma e munição.\n\nA banca pode afirmar que a rosa de tiro permite calcular a distância exata por tabela fixa. O certo é que a estimativa depende de ensaio.",
