        "rotulo": "Lei 9.434/1997, art. 4º",
        "texto": "A retirada de tecidos, órgãos e partes do corpo de pessoas falecidas para transplantes ou outra finalidade terapêutica, dependerá da autorização do cônjuge ou parente, maior de idade, obedecida a linha sucessória, reta ou colateral, até o segundo grau inclusive, firmada em documento subscrito por duas testemunhas presentes à verificação da morte."
