      "aprofundamento": "A cor dos livores depende do estado da hemoglobina no sangue. Normalmente são arroxeados, porque a hemoglobina está sem oxigênio. No envenenamento por **monóxido de carbono**, forma-se a **carboxiemoglobina**, de cor vermelho-viva, e os livores ficam rosados ou carminados.\n\nOutras situações também clareiam os livores, como o cianeto e a exposição ao frio. Por isso a cor é um indício que orienta o exame toxicológico, mas não fecha o diagnóstico sozinha.\n\nA banca pode afirmar que livores claros excluem intoxicação ou que são exclusivos do monóxido. Note o verbo da assertiva: 'podem'.",
