      "aprofundamento": "A exumação para fins periciais exige localizar a sepultura. A lei prevê situações em que isso não é simples: recusa ou falta de quem indique o local, ou cadáver enterrado fora de cemitério (como uma cova clandestina).\n\nNesses casos, a autoridade não fica impedida: procede às **pesquisas necessárias** para encontrar o corpo, e tudo deve constar do **auto**. O registro formal garante a regularidade da diligência e permite controle posterior sobre como e onde o corpo foi achado.\n\nA banca pode condicionar as pesquisas a autorização judicial ou dispensar o registro em auto. Nenhuma das duas condições está no texto.",
