     "assertiva": "A corificação é observada sobretudo em cadáveres sepultados em caixões de madeira, em solo úmido.",
     "gabarito": "E",
     "comentario": {
      "resumo": "A **corificação** (pele com aspecto de couro) é típica de corpos em **urnas metálicas hermeticamente fechadas**; o solo úmido e argiloso favorece a saponificação.",
      "pegadinha": "Trocar a condição que produz o fenômeno.",
      "palavras_chave": [
       "corificação",
       "urnas metálicas"
      ],
      "correcao": {
       "erro": "Associa a corificação a caixões de madeira em solo úmido.",
       "certo": "A corificação é típica de corpos em urnas metálicas hermeticamente fechadas; o solo úmido e argiloso favorece a saponificação."
      },
      "aprofundamento": "Os fenômenos conservadores dependem do ambiente em que o corpo fica. A **corificação** dá à pele aspecto e consistência de couro curtido, e é típica de corpos guardados em **urnas metálicas** hermeticamente fechadas, sobretudo de zinco, onde há pouca umidade e pouco ar circulando.\n\nO solo úmido e argiloso, com pouca oxigenação, favorece outro fenômeno: a **saponificação** (adipocera). Já os ambientes secos e ventilados favorecem a mumificação.\n\nA pegadinha troca a condição que produz cada fenômeno. Uma forma de fixar: corificação lembra caixão de metal fechado; saponificação lembra terra úmida; mumificação lembra ar seco.",
      "memorize": "Corificação: urna metálica fechada. Saponificação: solo úmido. Mumificação: ambiente seco e arejado."
     }
